insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Medieval','statement_based','easy','Consider the following statements regarding Babur and the founding of the Mughal Empire:','{"statements": ["Babur founded the Mughal Empire in India after defeating Ibrahim Lodi at the First Battle of Panipat in 1526.", "Babur made effective use of artillery and the Ottoman-style ''Tulughma'' tactic in this battle.", "Babur''s autobiography, the ''Baburnama'', was originally written in Persian, his native language."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Babur defeated Ibrahim Lodi at the First Battle of Panipat (1526) using artillery and Tulughma flanking tactics. Statement 3 is incorrect: the Baburnama was originally written in Chagatai Turkish, Babur''s native tongue, and was only later translated into Persian.','medieval-babur-first-panipat-1526','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapter on the founding of the Mughal Empire.','draft'),
('upsc','History','Medieval','statement_based','easy','Consider the following statements regarding the Sufi Chishti order in medieval India:','{"statements": ["The Chishti order was introduced to India by Khwaja Moinuddin Chishti, who settled at Ajmer.", "Sufi saints typically lived in hospices called ''Khanqahs'', which served as centres of spiritual and social activity.", "The Chishti order actively sought and accepted land grants and state patronage from Sultanate rulers as a central part of its practice."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Khwaja Moinuddin Chishti introduced the order at Ajmer, and Sufi saints commonly lived in Khanqahs. Statement 3 is incorrect: the Chishti order was known for deliberately avoiding state patronage and close association with political power -- a marked contrast with the Suhrawardi order, which did accept such patronage.','medieval-chishti-sufi-order','original_pattern_matched','NCERT, Themes in Indian History-II -- chapter on the Bhakti and Sufi movements.','draft'),
('upsc','History','Medieval','statement_based','easy','Consider the following statements regarding Sher Shah Suri''s administration:','{"statements": ["Sher Shah Suri, who briefly displaced the Mughals, introduced a new silver currency called the ''Rupiya''.", "He is credited with constructing/renovating the Grand Trunk Road connecting Bengal to the Indus region.", "Sher Shah Suri''s administrative reforms had no lasting influence on the later Mughal administration under Akbar."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Sher Shah Suri introduced the silver Rupiya and developed the Grand Trunk Road. Statement 3 is incorrect: his land revenue and currency reforms are widely regarded as having significantly influenced Akbar''s later administrative system.','medieval-sher-shah-suri-administration','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapter on Sher Shah Suri.','draft'),
('upsc','History','Medieval','statement_based','hard','Consider the following statements regarding Kabir and the Bhakti-Sufi confluence:','{"statements": ["Kabir''s religious identity remains debated among scholars, with traditions pointing to both Hindu and Muslim influences, some holding that he was raised in a Muslim weaver family.", "The Sufi concept of ''Wahdat-ul-Wujud'' (Unity of Being), associated with Ibn Arabi, found resonance among some Indian Sufi thinkers and is seen by some historians as paralleling certain Bhakti ideas of divine unity.", "There is unanimous scholarly agreement, with no historical dispute, that Kabir was formally initiated as a disciple of the Bhakti saint Ramananda."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Kabir''s background and influences are genuinely debated, and Wahdat-ul-Wujud is noted by historians as a point of resonance with certain Bhakti ideas. Statement 3 is incorrect: Kabir''s discipleship under Ramananda is itself a matter of historical and legendary uncertainty, not a point of unanimous, undisputed scholarly agreement.','medieval-kabir-bhakti-sufi-confluence','original_pattern_matched','NCERT, Themes in Indian History-II -- chapter on the Bhakti and Sufi movements.','draft'),
('upsc','History','Medieval','statement_based','hard','Consider the following statements regarding Shivaji and Maratha administration:','{"statements": ["Shivaji''s coronation in 1674 at Raigad involved a formal Vedic ceremony, presided over by the Brahmin scholar Gaga Bhatt.", "Aurangzeb''s prolonged Deccan campaigns against the Marathas, occupying much of the later part of his reign, are generally seen by historians as a major drain on Mughal resources and stability.", "Shivaji''s administrative council, the ''Ashtapradhan'', consisted of eight ministers, all of whom held hereditary, non-transferable positions passed down within fixed families."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Gaga Bhatt presided over Shivaji''s 1674 coronation, and Aurangzeb''s extended Deccan campaigns are widely regarded as having drained Mughal resources. Statement 3 is incorrect: Ashtapradhan positions were generally appointive rather than hereditary, made at the king''s discretion on the basis of merit, unlike older hereditary offices.','medieval-shivaji-maratha-administration','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapter on the rise of the Marathas.','draft'),
('upsc','History','Medieval','statement_based','hard','Consider the following statements regarding Akbar''s religious policy:','{"statements": ["''Sulh-i-Kul'' (peace with all), a broader policy principle of religious tolerance under Akbar, is often confused with but is distinct from ''Din-i-Ilahi'', his more specific syncretic religious order.", "The Ain-i-Akbari, part of the Akbarnama compiled by Abul Fazl, provides detailed administrative and statistical information about Akbar''s empire.", "Akbar himself never personally attended or participated in the interfaith religious discussions held at the Ibadat Khana (House of Worship) in Fatehpur Sikri."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Sulh-i-Kul and Din-i-Ilahi are related but distinct, and the Ain-i-Akbari (part of Abul Fazl''s Akbarnama) is a key administrative and statistical source. Statement 3 is incorrect: Akbar actively participated in and personally hosted interfaith discussions at the Ibadat Khana, a well-documented feature of his religious policy.','medieval-akbar-sulh-i-kul-ibadat-khana','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapter on Akbar''s religious policy.','draft'),
('upsc','History','Medieval','mcq','medium','Who was the founder of the Mughal Empire in India?','{}'::jsonb,'[{"id": "a", "body": "Humayun", "isCorrect": false}, {"id": "b", "body": "Babur", "isCorrect": true}, {"id": "c", "body": "Akbar", "isCorrect": false}, {"id": "d", "body": "Sher Shah Suri", "isCorrect": false}]'::jsonb,2,0.66,'Babur founded the Mughal Empire in India in 1526, after his victory at the First Battle of Panipat. Humayun was his son and successor (who briefly lost and later regained the throne), Akbar was his grandson who greatly expanded and consolidated the empire, and Sher Shah Suri was the Afghan ruler who temporarily displaced the Mughals between Humayun''s two reigns.','medieval-mughal-empire-founder','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapter on the founding of the Mughal Empire.','draft'),
('upsc','History','Medieval','mcq','medium','The ''Iqta'' system, an important feature of Delhi Sultanate administration, primarily referred to which of the following?','{}'::jsonb,'[{"id": "a", "body": "A tax levied specifically on non-Muslim subjects", "isCorrect": false}, {"id": "b", "body": "A territorial assignment of land revenue given to nobles/officers in lieu of salary", "isCorrect": true}, {"id": "c", "body": "A hereditary system of permanent land ownership for peasants", "isCorrect": false}, {"id": "d", "body": "A military rank system denoting cavalry strength", "isCorrect": false}]'::jsonb,2,0.66,'The Iqta system involved assigning territorial units to nobles and officers, who collected land revenue from them in lieu of a cash salary, in return for military and administrative service. It is distinct from the jizya (a tax on non-Muslims), was not a system of hereditary peasant land ownership, and is distinct from the Mansabdari rank system, which is a later Mughal institution.','medieval-iqta-system-delhi-sultanate','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapter on Delhi Sultanate administration.','draft'),
('upsc','History','Medieval','mcq','medium','Guru Arjan Dev, the fifth Sikh Guru, is credited with which of the following?','{}'::jsonb,'[{"id": "a", "body": "Founding the Khalsa Panth", "isCorrect": false}, {"id": "b", "body": "Founding the Sikh faith", "isCorrect": false}, {"id": "c", "body": "Compiling the Adi Granth and constructing the Harmandir Sahib (Golden Temple) at Amritsar", "isCorrect": true}, {"id": "d", "body": "Founding the city of Amritsar", "isCorrect": false}]'::jsonb,2,0.66,'Guru Arjan Dev compiled the Adi Granth (the core scripture later expanded into the Guru Granth Sahib) and built the Harmandir Sahib at Amritsar. The Khalsa Panth was founded later by Guru Gobind Singh, the Sikh faith itself was founded by Guru Nanak, and the city of Amritsar was founded earlier by Guru Ram Das, Arjan Dev''s father -- each a distinct contribution by a different Guru, commonly confused with one another.','medieval-guru-arjan-dev-adi-granth','original_pattern_matched','NCERT, Themes in Indian History-II -- chapter on the Sikh Gurus and the development of Sikhism.','draft'),
('upsc','History','Medieval','mcq','easy','Which Mughal emperor built the Taj Mahal?','{}'::jsonb,'[{"id": "a", "body": "Akbar", "isCorrect": false}, {"id": "b", "body": "Jahangir", "isCorrect": false}, {"id": "c", "body": "Shah Jahan", "isCorrect": true}, {"id": "d", "body": "Aurangzeb", "isCorrect": false}]'::jsonb,2,0.66,'The Taj Mahal was built by Shah Jahan in memory of his wife, Mumtaz Mahal. Akbar and Jahangir preceded Shah Jahan, and Aurangzeb was his son and successor -- none of the three is associated with the Taj Mahal''s construction.','medieval-taj-mahal-shah-jahan','original_pattern_matched','NCERT, Themes in Indian History-II -- chapter on Mughal architecture.','draft'),
('upsc','History','Medieval','mcq','easy','The First Battle of Panipat (1526), which laid the foundation of Mughal rule in India, was fought between Babur and which ruler?','{}'::jsonb,'[{"id": "a", "body": "Rana Sanga", "isCorrect": false}, {"id": "b", "body": "Sher Shah Suri", "isCorrect": false}, {"id": "c", "body": "Ibrahim Lodi", "isCorrect": true}, {"id": "d", "body": "Humayun", "isCorrect": false}]'::jsonb,2,0.66,'The First Battle of Panipat (1526) was fought between Babur and Ibrahim Lodi, the last ruler of the Delhi Sultanate''s Lodi dynasty, whom Babur defeated. Rana Sanga was defeated by Babur in a separate, later battle (Khanwa, 1527); Sher Shah Suri rose to prominence afterward, during Humayun''s reign; and Humayun was Babur''s own son, not an opposing ruler.','medieval-first-battle-panipat-1526','original_pattern_matched','NCERT, Themes in Indian History-II / Old NCERT Medieval India (Satish Chandra) -- chapter on the founding of the Mughal Empire.','draft'),
('upsc','History','Modern','mcq','hard','The ''Pact of 1932'' between Mahatma Gandhi and B. R. Ambedkar, which replaced separate electorates for the Depressed Classes with a system of reserved seats within the general electorate, is known as the:','{}'::jsonb,'[{"id": "a", "body": "Lucknow Pact", "isCorrect": false}, {"id": "b", "body": "Gandhi-Irwin Pact", "isCorrect": false}, {"id": "c", "body": "Poona Pact", "isCorrect": true}, {"id": "d", "body": "Delhi Pact", "isCorrect": false}]'::jsonb,2,0.66,'The Poona Pact (1932) replaced the Communal Award''s separate electorates for the Depressed Classes with reserved seats to be filled through joint electorates, following Gandhi''s fast against separate electorates. The Lucknow Pact (1916) concerned Congress-League cooperation; the Gandhi-Irwin Pact (1931) concerned the suspension of Civil Disobedience; and ''Delhi Pact'' is another name sometimes loosely applied to the Gandhi-Irwin Pact, not this agreement.','modern-poona-pact-naming-hard','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Communal Award and the Poona Pact.','draft'),
('upsc','History','Modern','mcq','hard','The ''August Kranti'' (August Revolution) of 1942 is an alternative name most closely associated with which movement?','{}'::jsonb,'[{"id": "a", "body": "Non-Cooperation Movement", "isCorrect": false}, {"id": "b", "body": "Civil Disobedience Movement", "isCorrect": false}, {"id": "c", "body": "Quit India Movement", "isCorrect": true}, {"id": "d", "body": "Individual Satyagraha", "isCorrect": false}]'::jsonb,2,0.66,'''August Kranti'' refers to the Quit India Movement, launched in August 1942 after the AICC''s Bombay resolution and Gandhi''s ''Do or Die'' call. The Non-Cooperation Movement (1920-22) and Civil Disobedience Movement (1930-34) belong to earlier phases of the struggle, and the Individual Satyagraha (1940) was a more limited, symbolic campaign preceding Quit India.','modern-august-kranti-quit-india','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Quit India Movement.','draft'),
('upsc','History','Modern','mcq','hard','The ''Karachi Resolution'' of the Indian National Congress, passed in 1931, is chiefly significant for which of the following?','{}'::jsonb,'[{"id": "a", "body": "It formally adopted the demand for Purna Swaraj (complete independence)", "isCorrect": false}, {"id": "b", "body": "It laid down the Congress''s vision of Fundamental Rights and economic policy for a future free India", "isCorrect": true}, {"id": "c", "body": "It ratified the Gandhi-Irwin Pact and endorsed the suspension of Civil Disobedience", "isCorrect": false}, {"id": "d", "body": "It formally split the Congress into Moderate and Extremist factions", "isCorrect": false}]'::jsonb,2,0.66,'The Karachi Resolution (1931) is chiefly remembered for articulating the Congress''s vision of Fundamental Rights and a broad economic and social policy programme for a future independent India. The Purna Swaraj demand had already been adopted earlier, at the Lahore Session (1929); ratifying the Gandhi-Irwin Pact was a related but separate agenda item at the same Karachi session, not the resolution''s chief significance; and the Moderate-Extremist split occurred decades earlier, at Surat (1907).','modern-karachi-resolution-1931','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Karachi Session and Fundamental Rights resolution.','draft'),
('upsc','History','Ancient','mcq','hard','The Junagadh Rock Inscription, one of the earliest known Sanskrit inscriptions of significant length, was issued by which ruler and is notable for recording repairs to which structure?','{}'::jsonb,'[{"id": "a", "body": "Ashoka; the Barabar Caves", "isCorrect": false}, {"id": "b", "body": "Rudradaman I; the Sudarshana Lake", "isCorrect": true}, {"id": "c", "body": "Samudragupta; the Mehrauli Iron Pillar", "isCorrect": false}, {"id": "d", "body": "Kharavela; the Hathigumpha Caves", "isCorrect": false}]'::jsonb,2,0.66,'The Junagadh Rock Inscription was issued by the Western Kshatrapa (Saka) ruler Rudradaman I and records his repair of the Sudarshana Lake, originally built under the Mauryas. Ashoka''s rock edicts are a separate body of inscriptions, mostly in Prakrit rather than the polished Sanskrit of this inscription; Samudragupta is associated with the Allahabad Prashasti and the Mehrauli Iron Pillar inscription is linked to a Chandra (traditionally identified with Chandragupta II); and Kharavela''s Hathigumpha inscription is a separate Kalinga-related record.','ancient-junagadh-rock-inscription-rudradaman','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Western Kshatrapas and epigraphic sources.','draft'),
('upsc','History','Ancient','mcq','hard','The Allahabad Prashasti (Pillar Inscription), composed by Harishena, is a key source for the reign and military campaigns of which Gupta ruler?','{}'::jsonb,'[{"id": "a", "body": "Chandragupta I", "isCorrect": false}, {"id": "b", "body": "Samudragupta", "isCorrect": true}, {"id": "c", "body": "Chandragupta II", "isCorrect": false}, {"id": "d", "body": "Kumaragupta I", "isCorrect": false}]'::jsonb,2,0.66,'The Allahabad Prashasti, composed by the court poet Harishena, eulogises Samudragupta''s military campaigns and is a principal source for reconstructing the extent of his conquests. Chandragupta I was Samudragupta''s father and predecessor; Chandragupta II and Kumaragupta I were later Gupta rulers, whose reigns are documented through separate, distinct inscriptions.','ancient-allahabad-prashasti-samudragupta','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Gupta Empire and Samudragupta''s conquests.','draft'),
('upsc','History','Ancient','mcq','hard','The Hathigumpha Inscription, an important source for the political history of ancient Kalinga, was issued by which ruler?','{}'::jsonb,'[{"id": "a", "body": "Kharavela", "isCorrect": true}, {"id": "b", "body": "Rudradaman I", "isCorrect": false}, {"id": "c", "body": "Ashoka", "isCorrect": false}, {"id": "d", "body": "Gautamiputra Satakarni", "isCorrect": false}]'::jsonb,2,0.66,'The Hathigumpha Inscription, found near Bhubaneswar, was issued by Kharavela, the Chedi/Mahameghavahana ruler of Kalinga, and details his reign and military campaigns. Rudradaman I''s comparable inscription is the Junagadh Rock Inscription; Ashoka''s Kalinga-related edicts (the Separate Kalinga Edicts) are a distinct set of records from an earlier period, prior to Kharavela; and Gautamiputra Satakarni is associated with the Nashik Prashasti, unrelated to Kalinga.','ancient-hathigumpha-inscription-kharavela','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on post-Mauryan regional kingdoms.','draft')
